// Limpiamos el objeto para que la IA no reciba 5MB de basura HTML del correo
const timestamp = new Date().toISOString().replace(/[-:T.]/g, '').substring(0, 14);
return items.map((item, index) => {
  const binaries = [];
  if (item.binary) {
    for (const key of Object.keys(item.binary)) {
      const uniqueId = Math.random().toString(36).substring(2, 6);
      const originalName = item.binary[key].fileName || 'archivo';
      const newFileName = `${timestamp}_${uniqueId}_${originalName}`;

      // Update the binary fileName property
      item.binary[key].fileName = newFileName;

      binaries.push({
        json: {
          fileName: newFileName,
          fileExtension: item.binary[key].fileExtension,
          originalMessageId: item.json.id,
          from: item.json.from.emailAddress.address
        },
        binary: {
          data: item.binary[key]
        },
        pairedItem: { item: index }
      });
    }
  }
  return binaries;
}).flat();

const output = [];

// Usamos i para mantener el índice y no romper el vínculo (Paired Item)
const timestamp = new Date().toISOString().replace(/[-:T.]/g, '').substring(0, 14);
for (let i = 0; i < items.length; i++) {
  const item = items[i];

  for (const key of Object.keys(item.binary || {})) {
    const bin = item.binary[key];
    const fileName = bin.fileName?.toLowerCase() || '';

    if (bin.mimeType === 'application/pdf' || fileName.endsWith('.pdf')) {
      const uniqueId = Math.random().toString(36).substring(2, 6);
      const originalName = bin.fileName || 'archivo.pdf';
      const newFileName = `${timestamp}_${uniqueId}_${originalName}`;

      bin.fileName = newFileName;

      output.push({
        // CLAVE: Usamos ...item.json para heredar TODO lo que venía de atrás
        // (ID del correo, fechas, metadata del servidor, etc.)
        json: { 
          ...item.json, 
          fileName: newFileName 
        },
        binary: { 
          data: bin 
        },
        // CLAVE 2: Le decimos a n8n exactamente de qué ítem de entrada viene este
        pairedItem: {
          item: i
        }
      });
    }
  }
}

return output;

const fecha = new Date();
const mesTexto = fecha.toLocaleString('es-CO', { month: 'long' });
const dia = fecha.getDate();
const anio = fecha.getFullYear();

return {
  json: {
    ...item.json,
    mes: mesTexto,
    dia: dia,
    anio: anio
  }
};

